# Generate a valid 1.5s mono 8kHz 16-bit PCM WAV (a quiet 220Hz tone) via Node
node -e '
const fs=require("fs");
const sr=8000, secs=1.5, n=Math.floor(sr*secs);
const data=Buffer.alloc(n*2);
for(let i=0;i<n;i++){const v=Math.round(Math.sin(2*Math.PI*220*i/sr)*3000);data.writeInt16LE(v,i*2);}
const hdr=Buffer.alloc(44);
hdr.write("RIFF",0);hdr.writeUInt32LE(36+data.length,4);hdr.write("WAVE",8);
hdr.write("fmt ",12);hdr.writeUInt32LE(16,16);hdr.writeUInt16LE(1,20);hdr.writeUInt16LE(1,22);
hdr.writeUInt32LE(sr,24);hdr.writeUInt32LE(sr*2,28);hdr.writeUInt16LE(2,32);hdr.writeUInt16LE(16,34);
hdr.write("data",36);hdr.writeUInt32LE(data.length,40);
fs.writeFileSync("/tmp/memo1.wav",Buffer.concat([hdr,data]));
fs.writeFileSync("/tmp/memo2.wav",Buffer.concat([hdr,data]));
console.log("wrote memo1.wav memo2.wav", 44+data.length, "bytes each");
'
