const bobReg = regId();
const bobPre = PrivateKey.generate();
const bobSigned = PrivateKey.generate();
const bobKyber = KEMKeyPair.generate();
const bobStores = { sess: new Sessions(), id: new Identities(bobId, bobReg), pre: new PreKeys(), signed: new SignedPreKeys(), kyber: new KyberPreKeys() };

