await bobStores.signed.saveSignedPreKey(1, SignedPreKeyRecord.new(1, Date.now(), bobSigned.getPublicKey(), bobSigned, signedSig));
await bobStores.kyber.saveKyberPreKey(1, KyberPreKeyRecord.new(1, Date.now(), bobKyber, kyberSig));

const bobBundle = PreKeyBundle.new(
  bobReg, 1, 1, bobPre.getPublicKey(), 1, bobSigned.getPublicKey(), signedSig,
  bobId.publicKey, 1, bobKyber.getPublicKey(), kyberSig,
);

// Alice establishes a session from Bob's bundle and encrypts
const aliceId = IdentityKeyPair.generate();
const aliceStores = { sess: new Sessions(), id: new Identities(aliceId, regId()) };
const bobAddr = ProtocolAddress.new("bob", 1);
const aliceAddr = ProtocolAddress.new("alice", 1);

await processPreKeyBundle(bobBundle, bobAddr, aliceStores.sess, aliceStores.id);
const plaintext = "meet me at the old radio tower at five";
const ct = await signalEncrypt(new TextEncoder().encode(plaintext), bobAddr, aliceStores.id === aliceStores.id ? aliceAddr : aliceAddr, aliceStores.sess, aliceStores.id);
console.log("ciphertext type:", ct.type(), "(3 = PreKey)");

