1	// The radio player store — single source of truth for the timeline and
2	// playback. Kept pure (persistence + object URLs are guarded side-effects) so
3	// its state transitions are unit-testable without a DOM.
4	//
5	// Playback follows the ACTIVE CHANNEL and the shuffle setting: the queue is
6	// memos filtered by channel, chronological or shuffled. currentIndex indexes
7	// into that queue, not the raw memos.
8	//
9	// Non-negotiables enforced here:
10	//  #3 the stream ends — next() past the last memo yields status "ended".
11	//  #4 no engagement machinery — likes are per-user state only, never counted.
12	
13	import { create } from "zustand";
14	import type { Channel, Memo, StoredMemo } from "@/lib/types";
15	import {
16	  getAllMemos,
17	  putMemo,
18	  setLiked as persistLiked,
19	  setCorrectedTranscript as persistCorrection,
20	} from "@/lib/idb";
21	import {
22	  ALL,
23	  DEFAULT_CHANNEL,
24	  channelQueue,
25	  loadChannels,
26	  orderedQueue,
27	  saveChannels,
28	  shuffleIds,
29	  uniqueChannelId,
30	} from "@/lib/channels";
31	
32	const TRANSCRIPTS_KEY = "tew:showTranscripts";
33	
34	function loadShowTranscripts(): boolean {
35	  if (typeof localStorage === "undefined") return true;
36	  try {
37	    return localStorage.getItem(TRANSCRIPTS_KEY) !== "false"; // default on
38	  } catch {
39	    return true;
40	  }
41	}
42	function saveShowTranscripts(v: boolean): void {
43	  if (typeof localStorage === "undefined") return;
44	  try {
45	    localStorage.setItem(TRANSCRIPTS_KEY, String(v));
46	  } catch {
47	    /* ignore quota/private-mode */
48	  }
49	}
50	
51	export type PlayerStatus = "idle" | "playing" | "paused" | "ended";
52	
53	type PlayerState = {
54	  memos: Memo[];
55	  urls: Record<string, string>; // memo id -> object URL
56	  channels: Channel[];
57	  activeChannel: string; // "all" or a channel id — drives the queue
58	  shuffle: boolean;
59	  shuffleOrder: string[]; // memo ids, when shuffle is on
60	  currentIndex: number; // index into the ACTIVE queue (channel + order)
61	  isPlaying: boolean;
62	  status: PlayerStatus;
63	  hydrated: boolean;
64	  replayNonce: number; // bumped to ask the player to seek current back to 0
65	  showTranscripts: boolean;
66	  playbackRate: number; // spoken-audio users often listen faster
67	
68	  hydrate: () => Promise<void>;
69	  addMemo: (
70	    blob: Blob,
71	    durationMs: number,
72	    mime: string,
73	    machineTranscript?: string,
74	  ) => Promise<Memo>;
75	  play: () => void;
76	  pause: () => void;
77	  togglePlay: () => void;
78	  next: () => void;
79	  previous: () => void;
80	  replay: () => void;
81	  playFrom: (queueIndex: number) => void;
82	  toggleLike: (id: string) => void;
83	  correctTranscript: (id: string, text: string) => void;
84	  toggleTranscripts: () => void;
85	  setActiveChannel: (id: string) => void;
86	  createChannel: (name: string) => void;
87	  toggleShuffle: () => void;
88	  cyclePlaybackRate: () => void;
89	  reset: () => void; // back to the start of the current queue
90	};
91	
92	export const PLAYBACK_RATES = [1, 1.25, 1.5, 2] as const;
93	
94	function makeId(): string {
95	  if (typeof crypto !== "undefined" && "randomUUID" in crypto) return crypto.randomUUID();
96	  return `memo_${Date.now()}_${Math.floor(Math.random() * 1e6)}`;
97	}
98	
99	function objectUrl(blob: Blob): string {
100	  if (typeof URL !== "undefined" && "createObjectURL" in URL) return URL.createObjectURL(blob);
101	  return "";
102	}
103	
104	// The active play-queue, honoring channel + shuffle.
105	function queueOf(s: {
106	  memos: Memo[];
107	  activeChannel: string;
108	  shuffle: boolean;
109	  shuffleOrder: string[];
110	}): Memo[] {
111	  return orderedQueue(s.memos, s.activeChannel, s.shuffle ? s.shuffleOrder : null);
112	}
113	
114	export const usePlayer = create<PlayerState>((set, get) => ({
115	  memos: [],
