// MARK: - v1 card deck
//
// Every action below is reachable three ways in the UI: the gesture, a
// labelled button, and a VoiceOver custom action. The rotor action is the one
// that actually reaches a blind user, since VoiceOver eats raw swipes.

public var deckCurrent: Memo? { deckCursor < queue.count ? queue[deckCursor] : nil }
public var deckNext: Memo? { deckCursor + 1 < queue.count ? queue[deckCursor + 1] : nil }
public var deckAtEnd: Bool { deckCursor >= queue.count }

private func likeCurrentIfNeeded() {
  guard let c = deckCurrent, !c.liked else { return }
  engine.toggleLike(c.id)
}

/// Swipe-right / Right-Arrow: like the card. A second like inside the window
/// is the "twice fast" double → like AND advance. Returns true if it advanced.
@discardableResult
public func likeIntent() -> Bool {
  guard deckCurrent != nil else { return false }
  likeCurrentIfNeeded()
  let now = Date().timeIntervalSince1970
  if isDoubleActivation(previous: lastLikeAt, now: now) {
    lastLikeAt = nil
    deckCursor += 1
    return true
  }
  lastLikeAt = now
  return false
}

/// The non-timed twin of the double-swipe.
public func likeAndNext() {
  guard deckCurrent != nil else { return }
  likeCurrentIfNeeded()
  lastLikeAt = nil
  deckCursor += 1
}

public func skipCard() {
  guard deckCurrent != nil else { return }
  lastLikeAt = nil
  deckCursor += 1
}

/// The precise route — unlike is possible here; swipe/arrow only ever like.
public func toggleLikeCurrent() {
  guard let c = deckCurrent else { return }
  engine.toggleLike(c.id)
}

public func restartDeck() {
  deckCursor = 0
  lastLikeAt = nil
}

