package com.thirdeyeworld.android

import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import androidx.lifecycle.ViewModel
import com.thirdeyeworld.core.ALL_CHANNELS
import com.thirdeyeworld.core.Channel
import com.thirdeyeworld.core.Memo
import com.thirdeyeworld.core.PlayerStatus
import com.thirdeyeworld.core.RadioEngine

/**
 * Drives the Compose UI off the verified [RadioEngine] (identical logic to web
 * + iOS). The engine is a mutable class, so after each action we mirror its
 * state into Compose [androidx.compose.runtime.State] to trigger recomposition.
 * Audio capture/playback + Media3 session are wired via [PlaybackService].
 */
class RadioViewModel : ViewModel() {
  private val engine = RadioEngine()

  var queue by mutableStateOf<List<Memo>>(emptyList()); private set
  var channels by mutableStateOf<List<Channel>>(engine.channels); private set
  var activeChannel by mutableStateOf(engine.activeChannel); private set
  var currentIndex by mutableStateOf(0); private set
  var status by mutableStateOf(PlayerStatus.IDLE); private set
  var isPlaying by mutableStateOf(false); private set
  var playbackRate by mutableStateOf(1.0); private set
  var isRecording by mutableStateOf(false); private set

  private fun sync() {
    queue = engine.queue
    channels = engine.channels
    activeChannel = engine.activeChannel
    currentIndex = engine.currentIndex
    status = engine.status
    isPlaying = engine.isPlaying
    playbackRate = engine.playbackRate
  }

  fun startRecording() { isRecording = true }
  fun stopRecording() {
    isRecording = false
    // TODO(device): real capture via AudioRecord/MediaRecorder → file + duration.
    val id = java.util.UUID.randomUUID().toString()
    engine.addMemo(
      Memo(id = id, createdAt = System.currentTimeMillis(), durationMs = 0, mime = "audio/m4a",
        channelId = if (activeChannel == ALL_CHANNELS) "main" else activeChannel),
    )
    sync()
  }

  fun play() { engine.play(); sync() }
  fun pause() { engine.pause(); sync() }
  fun togglePlay() { if (engine.isPlaying) engine.pause() else engine.play(); sync() }
  fun next() { engine.next(); sync() }
  fun previous() { engine.previous(); sync() }
  fun playFrom(i: Int) { engine.playFrom(i); sync() }
  fun toggleLike(id: String) { engine.toggleLike(id); sync() }
  fun selectChannel(id: String) { engine.setActiveChannel(id); sync(); restartDeck() }
  fun createChannel(name: String) { engine.createChannel(name); sync() }
  fun cyclePlaybackRate() { engine.cyclePlaybackRate(); sync() }

  fun stationName(id: String): String =
    if (id == ALL_CHANNELS) "All" else channels.firstOrNull { it.id == id }?.name ?: id

  // ---- v1 card deck ----
  //
  // Every action below is reachable three ways in the UI: the gesture, a
  // labelled button, and a TalkBack custom action. The custom action is the one
  // that actually reaches a blind user, since TalkBack eats raw swipes.

  var deckCursor by mutableStateOf(0); private set
  private var lastLikeAt: Long? = null

  val deckCurrent: Memo? get() = queue.getOrNull(deckCursor)
  val deckNext: Memo? get() = queue.getOrNull(deckCursor + 1)
  val deckAtEnd: Boolean get() = deckCursor >= queue.size

  private fun likeCurrentIfNeeded() {
    val c = deckCurrent ?: return
    if (!c.liked) { engine.toggleLike(c.id); sync() }
  }

  /** Swipe-right: like the card. A second like inside the window is the "twice
   *  fast" double → like AND advance. Returns true if it advanced. */
  fun likeIntent(): Boolean {
    deckCurrent ?: return false
    likeCurrentIfNeeded()
    val now = System.currentTimeMillis()
    if (isDoubleActivation(lastLikeAt, now)) {
      lastLikeAt = null
      deckCursor += 1
      return true
    }
    lastLikeAt = now
    return false
  }

  /** The non-timed twin of the double-swipe. */
  fun likeAndNext() {
    deckCurrent ?: return
    likeCurrentIfNeeded()
    lastLikeAt = null
    deckCursor += 1
  }

  fun skipCard() {
    deckCurrent ?: return
    lastLikeAt = null
    deckCursor += 1
  }

  /** The precise route — unlike is possible here; swipe only ever likes. */
  fun toggleLikeCurrent() {
    val c = deckCurrent ?: return
    engine.toggleLike(c.id)
    sync()
  }

  fun restartDeck() {
    deckCursor = 0
    lastLikeAt = null
  }
}

import Foundation
import ThirdEyeCore

// Assert-based self-check — XCTest/swift-testing need Xcode, absent here, so we
// verify behavior by running the engine and exiting non-zero on any failure.
// Mirrors the web store's unit tests.

var passed = 0

@MainActor
func check(_ cond: Bool, _ msg: String) {
  if cond {
    passed += 1
  } else {
    FileHandle.standardError.write(Data("✗ FAILED: \(msg)\n".utf8))
    exit(1)
  }
}

func memo(_ id: String, channel: String = "main", transcript: String = "") -> Memo {
  Memo(id: id, createdAt: 0, durationMs: 1000, mime: "audio/webm", channelId: channel,
       machineTranscript: transcript)
}

// addMemo + queue
do {
  var e = RadioEngine()
  e.addMemo(memo("a"))
  e.addMemo(memo("b"))
  check(e.memos.count == 2, "adds memos")
  check(e.queue.count == 2, "all-channel queue holds both")
}

// next advances then ends the stream (#3)
do {
  var e = RadioEngine()
  e.addMemo(memo("a"))
  e.addMemo(memo("b"))
  e.play()
  e.next()
  check(e.currentIndex == 1, "next advances")
  e.next()
  check(e.status == .ended && !e.isPlaying, "the stream ends past the last memo")
}

// previous clears ended, clamps at 0
do {
  var e = RadioEngine()
  e.addMemo(memo("a"))
  e.addMemo(memo("b"))
  e.play(); e.next(); e.next()  // ended
  e.previous()
  check(e.currentIndex == 0 && e.status == .paused, "previous steps back and clears ended")
  e.previous()
  check(e.currentIndex == 0, "previous clamps at start")
}

// channels: posting follows the active station; queue filters; all aggregates
do {
  var e = RadioEngine()
  e.addMemo(memo("m1"))            // -> main (active is "all")
  e.createChannel("Music")         // active becomes "music"
  e.addMemo(memo("m2"))            // -> music
  check(e.channels.contains(where: { $0.id == "music" }), "createChannel slugs an id")
  e.setActiveChannel("music")
  check(e.queue.map(\.id) == ["m2"], "queue follows the active station")
  e.setActiveChannel(allChannels)
  check(e.queue.count == 2, "'all' aggregates every station")
}

// shuffle: injected order is applied; late memos appended
do {
  var e = RadioEngine()
  e.addMemo(memo("x")); e.addMemo(memo("y")); e.addMemo(memo("z"))
  e.setShuffleOrder(["z", "x", "y"])
  check(e.queue.map(\.id) == ["z", "x", "y"], "shuffle order is applied")
  e.disableShuffle()
  check(e.queue.map(\.id) == ["x", "y", "z"], "disabling shuffle restores chronological")
}

// playback rate cycles 1 -> 1.25 -> 1.5 -> 2 -> 1
do {
  var e = RadioEngine()
  check(e.playbackRate == 1, "default rate 1x")
  e.cyclePlaybackRate(); check(e.playbackRate == 1.25, "rate 1.25x")
  e.cyclePlaybackRate(); e.cyclePlaybackRate(); check(e.playbackRate == 2, "rate 2x")
  e.cyclePlaybackRate(); check(e.playbackRate == 1, "rate wraps to 1x")
}

// transcript correction never overwrites the machine text (#8.3)
do {
  var e = RadioEngine()
  e.addMemo(memo("d", transcript: "helo ther"))
  let id = e.memos[0].id
  e.correctTranscript(id, "  hello there  ")
  check(e.memos[0].machineTranscript == "helo ther", "machine transcript preserved")
  check(e.memos[0].displayTranscript == "hello there", "correction shown + trimmed")
}

// helpers
check(slugify("My Cool Station!") == "my-cool-station", "slugify")
check(uniqueChannelId("Main", [Channel(id: "main", name: "Main")]) == "main-2", "unique channel id")

// v1 card-deck gestures — mirrors the web lib/gestures.ts unit tests so the
// platforms cannot drift apart on what counts as a like / skip / double.
check(classifySwipe(dx: 120, dy: 10) == .like, "swipe right past threshold = like")
check(classifySwipe(dx: -120, dy: -10) == .skip, "swipe left past threshold = skip")
check(classifySwipe(dx: 50, dy: 0) == nil, "short drag is not a decision")
check(classifySwipe(dx: 120, dy: 200) == nil, "mostly-vertical drag is left for scrolling")
check(classifySwipe(dx: swipeThresholdPoints, dy: 0) == .like, "decisive right at the threshold")
check(isDoubleActivation(previous: nil, now: 1) == false, "no previous activation = not a double")
check(isDoubleActivation(previous: 1.0, now: 1.3) == true, "second activation inside the window")
check(isDoubleActivation(previous: 1.0, now: 1.5) == false, "past the window = not a double")
check(isDoubleActivation(previous: 1.5, now: 1.0) == false, "non-monotonic clock = not a double")

print("✓ \(passed) ThirdEyeCore checks passed")

