1	// Channels / stations (Slice 1b). The play-queue is a pure function of the
2	// memos and the active channel — no stored order (shuffle is a later slice).
3	import type { Channel, Memo } from "./types";
4	
5	export const DEFAULT_CHANNEL: Channel = { id: "main", name: "Main" };
6	export const ALL = "all";
7	
8	const KEY = "tew:channels";
9	
10	export function loadChannels(): Channel[] {
11	  if (typeof localStorage === "undefined") return [DEFAULT_CHANNEL];
12	  try {
13	    const raw = localStorage.getItem(KEY);
14	    if (!raw) return [DEFAULT_CHANNEL];
15	    const parsed = JSON.parse(raw) as Channel[];
16	    return Array.isArray(parsed) && parsed.length ? parsed : [DEFAULT_CHANNEL];
17	  } catch {
18	    return [DEFAULT_CHANNEL];
19	  }
20	}
21	
22	export function saveChannels(channels: Channel[]): void {
23	  if (typeof localStorage === "undefined") return;
24	  try {
25	    localStorage.setItem(KEY, JSON.stringify(channels));
26	  } catch {
27	    /* private mode / quota — channels just won't persist */
28	  }
29	}
30	
31	/** The queue for a given active channel. "all" plays everything, chronological. */
32	export function channelQueue(memos: Memo[], activeChannel: string): Memo[] {
33	  return activeChannel === ALL ? memos : memos.filter((m) => m.channelId === activeChannel);
34	}
35	
